def select_next_node(graph, unvisited_nodes):
    if graph is None or not unvisited_nodes:
        return None

    nodes_all = list(graph.nodes())
    if not nodes_all:
        return None

    seen = set()
    candidates: List[Any] = []
    for node in unvisited_nodes:
        if node in graph and node not in seen:
            seen.add(node)
            candidates.append(node)
    if not candidates:
        return None

    def mean_std(values):
        if not values:
            return 0.0, 1.0
        mean_val = sum(values) / len(values)
        variance = sum((v - mean_val) ** 2 for v in values) / len(values)
        std_val = math.sqrt(variance)
        if std_val < 1e-9:
            std_val = 1.0
        return mean_val, std_val

    def zscore(value, mean_val, std_val):
        if std_val < 1e-9:
            return 0.0
        return (value - mean_val) / std_val

    def minmax_normalize(mapping: Dict[Any, float]):
        if not mapping:
            return {}
        values = list(mapping.values())
        min_v = min(values)
        max_v = max(values)
        if max_v - min_v < 1e-9:
            return {k: 0.0 for k in mapping}
        return {k: (v - min_v) / (max_v - min_v) for k, v in mapping.items()}

    feature_data: Dict[Any, Dict[str, float]] = {}
    deg_vals, core_vals, bet_vals, eig_vals, impact_vals = [], [], [], [], []

    for node in nodes_all:
        data = graph.nodes[node]
        degree = data.get("degree")
        if degree is None:
            degree = float(graph.degree(node))
        core_number = data.get("core_number", 0.0)
        betweenness = data.get("betweenness", 0.0)
        eigenvector = data.get("eigenvector", 0.0)
        clustering = data.get("clustering", 0.0)
        if clustering is None:
            clustering = 0.0
        clustering = max(0.0, min(1.0, clustering))
        impact = 1.0 - clustering

        feature_data[node] = {
            "degree": float(degree),
            "core": float(core_number),
            "bet": float(betweenness),
            "eig": float(eigenvector),
            "impact": float(impact),
        }
        deg_vals.append(feature_data[node]["degree"])
        core_vals.append(feature_data[node]["core"])
        bet_vals.append(feature_data[node]["bet"])
        eig_vals.append(feature_data[node]["eig"])
        impact_vals.append(feature_data[node]["impact"])

    deg_mean, deg_std = mean_std(deg_vals)
    core_mean, core_std = mean_std(core_vals)
    bet_mean, bet_std = mean_std(bet_vals)
    eig_mean, eig_std = mean_std(eig_vals)
    impact_mean, impact_std = mean_std(impact_vals)

    deg_z = {n: zscore(feature_data[n]["degree"], deg_mean, deg_std) for n in nodes_all}
    core_z = {n: zscore(feature_data[n]["core"], core_mean, core_std) for n in nodes_all}
    bet_z = {n: zscore(feature_data[n]["bet"], bet_mean, bet_std) for n in nodes_all}
    eig_z = {n: zscore(feature_data[n]["eig"], eig_mean, eig_std) for n in nodes_all}
    impact_z = {n: zscore(feature_data[n]["impact"], impact_mean, impact_std) for n in nodes_all}

    adjacency = {node: list(graph.neighbors(node)) for node in nodes_all}
    sorted_by_degree = sorted(nodes_all, key=lambda n: feature_data[n]["degree"], reverse=True)
    target10 = set(sorted_by_degree[:min(10, len(sorted_by_degree))])
    target50 = set(sorted_by_degree[:min(50, len(sorted_by_degree))])

    rng = random.Random(1337)

    def compute_hitting_times(target_set, max_steps):
        times = {}
        for node in candidates:
            if node in target_set or max_steps <= 0:
                times[node] = 0.0
                continue
            total = 0.0
            for _ in range(8):
                current = node
                hit_step = max_steps + 1
                for step in range(1, max_steps + 1):
                    neighbors = adjacency.get(current, [])
                    if not neighbors:
                        break
                    current = rng.choice(neighbors)
                    if current in target_set:
                        hit_step = step
                        break
                total += hit_step
            times[node] = total / 8.0
        return times

    fht10 = compute_hitting_times(target10, 7)
    fht50 = compute_hitting_times(target50, 11)

    combined = {}
    for node in candidates:
        num = 0.65 * fht10.get(node, 8.0) + 0.35 * fht50.get(node, 12.0) + 1e-9
        combined[node] = 1.0 / num
    t_bonus = minmax_normalize(combined)

    base_weights = {
        "deg": 0.30,
        "core": 0.23,
        "bet": 0.18,
        "eig": 0.12,
        "impact": 0.17,
    }

    precomputed = graph.graph.get("precomputed", {}) if isinstance(graph.graph, dict) else {}
    bridge_ratio = precomputed.get("bridge_ratio_high_bc", 0.0) or 0.0
    degree_variance = precomputed.get("degree_variance", 0.0) or 0.0
    bridge_amp = min(0.05, 0.01 * bridge_ratio)
    degree_amp = min(0.05, 0.002 * degree_variance)

    base_scores = {}
    final_scores = {}
    for node in candidates:
        base_score = (
            base_weights["deg"] * deg_z.get(node, 0.0)
            + base_weights["core"] * core_z.get(node, 0.0)
            + base_weights["bet"] * bet_z.get(node, 0.0)
            + base_weights["eig"] * eig_z.get(node, 0.0)
            + base_weights["impact"] * impact_z.get(node, 0.0)
        )
        base_scores[node] = base_score

        bonus = t_bonus.get(node, 0.0)
        score = 0.72 * base_score + 0.28 * bonus
        score += bridge_amp * (1.0 + eig_z.get(node, 0.0))
        score += degree_amp * deg_z.get(node, 0.0)
        final_scores[node] = score

    ordered = sorted(candidates, key=lambda n: final_scores[n], reverse=True)
    if not ordered:
        return None

    fht10_values_sorted = sorted(fht10[node] for node in candidates)
    total_vals = len(fht10_values_sorted)

    percentile_map = {}
    for node in candidates:
        idx = bisect_right(fht10_values_sorted, fht10[node])
        percentile_map[node] = idx / total_vals if total_vals else 1.0

    start_k = min(55, len(ordered))
    start_k = max(start_k, 1)
    k = start_k
    max_limit = min(85, len(ordered))

    i = k
    while i < max_limit:
        prev_score = final_scores[ordered[i - 1]]
        curr_score = final_scores[ordered[i]]
        drop = max(0.0, prev_score - curr_score)
        percentile = percentile_map.get(ordered[i], 1.0)
        if drop < 0.011 and percentile <= 0.65:
            k += 1
            i += 1
        else:
            break

    selected_nodes = ordered[:k]
    next_node = selected_nodes[0] if selected_nodes else None
    return next_node

