def select_next_node(graph, unvisited_nodes):
    if not unvisited_nodes:
        return None

    precomputed = graph.graph.get('precomputed', {}) or {}

    degrees = {}
    for node in graph.nodes:
        deg_val = graph.nodes[node].get('degree')
        if deg_val is None:
            deg_val = graph.degree(node)
        degrees[node] = deg_val

    avg_degree = precomputed.get('avg_degree')
    if avg_degree is None:
        avg_degree = sum(degrees.values()) / len(degrees)

    degree_var = precomputed.get('degree_variance')
    if degree_var is None:
        degree_mean_sq = sum((deg - avg_degree) ** 2 for deg in degrees.values())
        degree_var = degree_mean_sq / len(degrees)
    degree_std = math.sqrt(degree_var) if degree_var and degree_var > 0 else 1.0

    cores = {}
    for node in graph.nodes:
        cores[node] = graph.nodes[node].get('core_number', 0)

    core_mean = sum(cores.values()) / len(cores)
    core_var = sum((core - core_mean) ** 2 for core in cores.values()) / len(cores)
    core_std = math.sqrt(core_var) if core_var and core_var > 0 else 1.0

    bet_logs = {}
    max_bet_log = 0.0
    for node in graph.nodes:
        bet_val = graph.nodes[node].get('betweenness', 0.0)
        log_val = math.log1p(bet_val)
        bet_logs[node] = log_val
        if log_val > max_bet_log:
            max_bet_log = log_val
    bet_norm = {node: (bet_logs[node] / max_bet_log) if max_bet_log > 0 else 0.0 for node in graph.nodes}

    scores = {}
    for node in graph.nodes:
        degree_z = (degrees[node] - avg_degree) / degree_std
        core_z = (cores[node] - core_mean) / core_std
        score = 0.50 * degree_z + 0.25 * core_z + 0.25 * bet_norm[node]
        scores[node] = score

    next_node = max(unvisited_nodes, key=lambda n: (scores.get(n, float('-inf')), n))
    return next_node

