        metrics['core_number'][n] = float(data.get('core_number', 0.0))
        metrics['betweenness'][n] = float(data.get('betweenness', 0.0))
        metrics['clustering'][n] = float(data.get('clustering', 0.0))
        metrics['eigenvector'][n] = float(data.get('eigenvector', 0.0))

    def normalize(values_dict):
        arr = np.array(list(values_dict.values()), dtype=float)
        if arr.size == 0:
            return {n: 0.0 for n in values_dict}
        median = float(np.median(arr))
        mad = float(np.median(np.abs(arr - median)))
        if mad < 1e-9:
            std = float(np.std(arr))
            denom = std if std > 1e-9 else 1.0
        else:
            denom = mad
        return {n: (val - median) / denom for n, val in values_dict.items()}

    deg_norm = normalize(metrics['degree'])
    core_norm = normalize(metrics['core_number'])
    bet_norm = normalize(metrics['betweenness'])
    clust_norm = normalize(metrics['clustering'])
    eigen_norm = normalize(metrics['eigenvector'])

