            0.35 * deg_norm.get(n, 0.0) +
            0.25 * core_norm.get(n, 0.0) +
            0.25 * bet_norm.get(n, 0.0) +
            0.15 * clust_norm.get(n, 0.0)
        )

    base_array = np.array(list(base_scores.values()), dtype=float)
    if base_array.size >= 3:
        low_th = float(np.percentile(base_array, 33.33))
        high_th = float(np.percentile(base_array, 66.66))
    else:
        low_th = high_th = float(base_array.mean()) if base_array.size else 0.0

    best_node = None
    best_score = -float('inf')

    for node in unvisited_nodes:
        if node not in base_scores:
            continue
        base = base_scores[node]
        eig = eigen_norm.get(node, 0.0)

        if base >= high_th:
            refined = 0.5 * base + 0.5 * eig
        elif base >= low_th:
            refined = 0.6 * base + 0.4 * eig
        else:
            refined = 0.7 * base + 0.3 * eig

        score = refined + 0.15 * bridge_ratio * bet_norm.get(node, 0.0)

        if degree_variance < 2.0:
            score += 0.05 * clust_norm.get(node, 0.0)

        if diameter_lcc > 8.0:
            score += 0.05 * core_norm.get(node, 0.0)

        if score > best_score or (score == best_score and base > base_scores.get(best_node, -float('inf'))):
            best_score = score
            best_node = node

    return best_node

