    total_nodes = len(node_cache)
    if total_nodes == 0:
        return None

    means = {feat: (sums[feat] / total_nodes if total_nodes else 0.0) for feat in sums}
    if "avg_degree" in precomputed:
        means["degree"] = float(precomputed["avg_degree"])

    # Compute standard deviations.
    variances = {feat: 0.0 for feat in sums}
    for data in node_cache.values():
        for feat in sums:
            diff = data[feat] - means[feat]
            variances[feat] += diff * diff

    stds = {}
    for feat in sums:
        if feat == "degree" and "degree_variance" in precomputed:
            stds[feat] = math.sqrt(max(float(precomputed["degree_variance"]), 1e-12))
        else:
            variance = variances[feat] / total_nodes if total_nodes else 0.0
            stds[feat] = math.sqrt(variance) if variance > 1e-12 else 0.0

    def zscore(value, mean, std):
        return (value - mean) / std if std > 1e-12 else 0.0

    normalized_map = {}
    for node, data in node_cache.items():
        normalized_map[node] = {
            "degree": zscore(data["degree"], means["degree"], stds["degree"]),
            "core": zscore(data["core"], means["core"], stds["core"]),
            "betweenness": zscore(data["betweenness"], means["betweenness"], stds["betweenness"]),
            "eigen": zscore(data["eigen"], means["eigen"], stds["eigen"]),
            "cluster_comp": zscore(data["cluster_comp"], means["cluster_comp"], stds["cluster_comp"]),
        }

    base_scores = {}
    candidate_info = {}
    for node in unvisited:
        if node not in node_cache:
            continue
        neighbors = list(graph.neighbors(node))
        unvisited_neighbor_count = sum(1 for nbr in neighbors if nbr in unvisited_set)
        frontier_ratio = (unvisited_neighbor_count + 0.5) / (len(neighbors) + 1.0)

        norms = normalized_map.get(node, {})
        score = (
            weights["degree"] * norms.get("degree", 0.0)
            + weights["core"] * norms.get("core", 0.0)
            + weights["betweenness"] * norms.get("betweenness", 0.0)
            + weights["eigen"] * norms.get("eigen", 0.0)
            + weights["cluster_comp"] * norms.get("cluster_comp", 0.0)
            + weights["frontier"] * frontier_ratio
        )

        base_scores[node] = score
        candidate_info[node] = {
            "neighbors": neighbors,
            "frontier": frontier_ratio,
            "unvisited_neighbors": unvisited_neighbor_count,
        }

    if not base_scores:
        return nodes_available[0]

    sorted_candidates = sorted(base_scores, key=lambda n: base_scores[n], reverse=True)
    beam_nodes = sorted_candidates[:beam_width]
    expand_limit = min(len(sorted_candidates), max(beam_width, int(math.ceil(beam_width * expansion_factor))))
    candidate_list = sorted_candidates[:expand_limit]

    centroid = {}
    if beam_nodes:
        for feat in ["degree", "core", "betweenness", "eigen", "cluster_comp"]:
            centroid[feat] = sum(normalized_map[node][feat] for node in beam_nodes) / len(beam_nodes)

    bridge_ratio = float(precomputed.get("bridge_ratio_high_bc", 0.0)) if precomputed else 0.0

    best_node = None
    best_score = -float("inf")

    for node in candidate_list:
        base = base_scores[node]
        info = candidate_info[node]
        frontier_ratio = info["frontier"]
        neighbors = info["neighbors"]

        neighbor_scores = []
        for nbr in neighbors:
            if nbr in base_scores:
                neighbor_scores.append(base_scores[nbr])
        neighbor_scores.sort(reverse=True)
        neighbor_scores = neighbor_scores[:swap_candidates]

        best_neighbor_gain = 0.0
        for nb_score in neighbor_scores:
            if nb_score > base:
                best_neighbor_gain = max(best_neighbor_gain, nb_score - base)
        swap_bonus = acceptance_prob * (local_swap_rounds / (local_swap_rounds + 1.0)) * min(best_neighbor_gain, 1.5)

        local_bonus = (frontier_ratio ** 1.2) * (local_swap_rounds * 0.2) + 0.1 * math.log1p(info["unvisited_neighbors"])
        bridging_bonus = 0.04 * bridge_ratio * max(normalized_map[node]["betweenness"], 0.0)

        penalty = 0.0
        if centroid:
            diff_sq = 0.0
            for feat in centroid:
                diff = normalized_map[node][feat] - centroid[feat]
                diff_sq += diff * diff
            similarity = 1.0 / (1.0 + math.sqrt(diff_sq))
            penalty = diversity_penalty * similarity

        refined = base + swap_bonus + local_bonus + bridging_bonus - penalty

        if refined > best_score:
            best_score = refined
            best_node = node

    if best_node is None and fallback_greedy:
        best_node = sorted_candidates[0] if sorted_candidates else nodes_available[0]

    return best_node

import math

def select_next_node(graph, unvisited_nodes):
    if not unvisited_nodes:
        return None

    nodes = list(graph.nodes)
    if not nodes:
        return None

    attr_names = ["degree", "clustering", "core_number", "betweenness", "eigenvector"]
    attr_data = {attr: {} for attr in attr_names}

    for node in nodes:
        data = graph.nodes[node]
        for attr in attr_names:
            attr_data[attr][node] = float(data.get(attr, 0.0))

    def normalize(values_dict):
        if not values_dict:
            return {}
        min_val = min(values_dict.values())
        max_val = max(values_dict.values())
        if max_val - min_val < 1e-12:
            return {node: 0.0 for node in values_dict}
        denom = max_val - min_val
        return {node: (val - min_val) / denom for node, val in values_dict.items()}

    deg_norm = normalize(attr_data["degree"])
    core_norm = normalize(attr_data["core_number"])
    bet_norm = normalize(attr_data["betweenness"])
    eig_norm = normalize(attr_data["eigenvector"])

    inv_clust_raw = {}
    for node, clust in attr_data["clustering"].items():
        clamped_clust = max(0.0, min(1.0, clust))
        inv_clust_raw[node] = 1.0 - clamped_clust
    inv_clust_norm = normalize(inv_clust_raw)

    core_cutoff = 0.6
    bet_cutoff = 0.5
    candidates = [
        node for node in unvisited_nodes
        if node in deg_norm and (core_norm.get(node, 0.0) >= core_cutoff or bet_norm.get(node, 0.0) >= bet_cutoff)
    ]
    if not candidates:
        candidates = [node for node in unvisited_nodes if node in deg_norm]
    if not candidates:
        return None

    precomputed = graph.graph.get("precomputed", {}) or {}
    bridge_ratio = float(precomputed.get("bridge_ratio_high_bc", 0.0))
    avg_degree = float(precomputed.get("avg_degree", 0.0))
    degree_variance = float(precomputed.get("degree_variance", 0.0))
    if avg_degree <= 0.0:
        avg_degree = 1.0
    degree_var_factor = min(1.0, degree_variance / (avg_degree * avg_degree + 1e-12))

    best_node = None
    best_score = -math.inf

    for node in candidates:
        deg_n = deg_norm.get(node, 0.0)
        core_n = core_norm.get(node, 0.0)
        inv_n = inv_clust_norm.get(node, 0.0)
        bet_n = bet_norm.get(node, 0.0)
        eig_n = eig_norm.get(node, 0.0)
        clustering = attr_data["clustering"].get(node, 0.0)

        base_score = (
            0.28 * deg_n
            + 0.22 * core_n
            + 0.18 * inv_n
            + 0.17 * bet_n
            + 0.15 * eig_n
        )
        adjustment = (
            0.07 * bridge_ratio * bet_n
            + 0.04 * degree_var_factor * deg_n
            + 0.06 * max(0.0, 1.0 - clustering)
            - 0.03 * clustering
        )
        final_score = base_score + adjustment

        if final_score > best_score:
            best_score = final_score
            best_node = node
        elif math.isclose(final_score, best_score):
            if deg_n > deg_norm.get(best_node, 0.0):
                best_node = node

    return best_node

import math

def select_next_node(graph, unvisited_nodes):
    if not unvisited_nodes:
        return None

    unvisited = list(dict.fromkeys(unvisited_nodes))
    total_nodes = max(graph.number_of_nodes(), 1)

    def zscore_map(attr, transform=None):
        values = {}
        for node in graph.nodes:
            val = graph.nodes[node].get(attr, 0.0)
            if transform is not None:
                val = transform(val)
            values[node] = float(val)
        if not values:
            return {}
        mean = sum(values.values()) / len(values)
        var = sum((val - mean) ** 2 for val in values.values()) / len(values)
        std = math.sqrt(var) if var > 1e-12 else 1.0
        return {node: (val - mean) / std for node, val in values.items()}

    z_degree = zscore_map('degree')
    z_core = zscore_map('core_number')
    z_inv_clust = zscore_map('clustering', transform=lambda c: 1.0 - c)
    z_betweenness = zscore_map('betweenness')
    z_eigenvector = zscore_map('eigenvector')

    scores = {}
    for node in unvisited:
        scores[node] = (
            0.30 * z_degree.get(node, 0.0)
            + 0.22 * z_core.get(node, 0.0)
            + 0.16 * z_inv_clust.get(node, 0.0)
            + 0.17 * z_betweenness.get(node, 0.0)
            + 0.15 * z_eigenvector.get(node, 0.0)
        )

    sorted_nodes = sorted(unvisited, key=lambda n: scores[n], reverse=True)
    reciprocal_ranks = {}
    prev_score = None
    current_rank = 0
    for idx, node in enumerate(sorted_nodes):
        if prev_score is None or not math.isclose(scores[node], prev_score, rel_tol=1e-12, abs_tol=1e-12):
            current_rank = idx + 1
            prev_score = scores[node]
        reciprocal_ranks[node] = 1.0 / current_rank

    blends = {node: 0.65 * scores[node] + 0.35 * reciprocal_ranks[node] for node in unvisited}

    anc_prefix_k = len(unvisited) / total_nodes
    k_raw = 60 + 10 * (anc_prefix_k - 0.85) / 0.01
    k_base = max(60, min(72, int(round(k_raw))))
    if anc_prefix_k > 0:
        adjust_factor = 0.8563 / anc_prefix_k
    else:
        adjust_factor = 1.0
    adjust_factor = max(0.5, min(1.5, adjust_factor))
    k_adjusted = max(1, int(round(k_base * adjust_factor)))
    k = min(len(unvisited), k_adjusted)

    precomputed = graph.graph.get('precomputed', {})
    max_core = precomputed.get('max_core_k', 1.0)
    if not max_core:
        max_core = 1.0

    final_scores = {}
    for node in unvisited:
        core_ratio = graph.nodes[node].get('core_number', 0.0) / max_core
        final_scores[node] = blends[node] + 0.02 * core_ratio

    candidates = sorted_nodes[:k] if k < len(sorted_nodes) else sorted_nodes
    next_node = max(
        candidates,
        key=lambda n: (final_scores[n], graph.nodes[n].get('degree', 0.0))
    )
    return next_node

def select_next_node(graph, unvisited_nodes):
    pre = getattr(graph, "graph", {}).get("precomputed", {}) or {}
    avg_degree = pre.get("avg_degree", 1.0) or 1.0
    degree_variance = pre.get("degree_variance", avg_degree) or avg_degree
    apl = pre.get("apl_lcc", 1.0) or 1.0
    diameter = pre.get("diameter_lcc", max(apl, 1.0)) or max(apl, 1.0)
    max_core = pre.get("max_core_k", 1.0) or 1.0
    bridge_ratio = pre.get("bridge_ratio_high_bc", 0.0) or 0.0

    total_nodes = max(graph.number_of_nodes(), 1)
    remaining = max(len(unvisited_nodes), 1)
    progress = 1.0 - remaining / total_nodes

    hetero = min(2.5, degree_variance / (avg_degree + 1e-9))
    stretch = min(1.0, apl / (diameter + 1e-9))
    core_bias = min(1.0, max_core / (avg_degree + 1e-9))

    cache = graph.graph.setdefault("_novel_selector_cache", {})
    attr_names = ["degree", "core_number", "betweenness", "eigenvector"]
    if cache.get("_size") != total_nodes:
        nodes_list = list(graph.nodes)
        cache["_size"] = total_nodes
        for attr in attr_names:
            values = [graph.nodes[n].get(attr, 0.0) for n in nodes_list]
            if not values:
                cache[attr] = {node: 0.5 for node in nodes_list}
                continue
            v_min = min(values)
            v_max = max(values)
            span = v_max - v_min
            if span <= 1e-12:
                cache[attr] = {node: 0.5 for node in nodes_list}
            else:
                cache[attr] = {
                    node: (val - v_min) / span
                    for node, val in zip(nodes_list, values)
                }

    def norm_lookup(attr, node):
        return cache.get(attr, {}).get(node, 0.0)

    def clamp(val, low, high):
        return max(low, min(high, val))

    thr_deg = clamp(0.55 - 0.2 * progress + 0.12 * hetero, 0.35, 0.9)
    thr_core = clamp(0.35 + 0.3 * core_bias - 0.15 * progress + 0.25 * (1.0 - stretch), 0.25, 0.9)
    thr_bridge = clamp(0.58 - 0.22 * progress + 0.2 * bridge_ratio, 0.3, 0.9)
    thr_eig = clamp(0.5 - 0.3 * progress + 0.05 * hetero, 0.15, 0.65)
    thr_open = clamp(0.55 + 0.15 * (1.0 - stretch) - 0.2 * progress, 0.35, 0.9)

    best_node = None
    best_value = float("-inf")

    for node in unvisited_nodes:
        node_data = graph.nodes[node]
        deg_norm = norm_lookup("degree", node)
        core_norm = norm_lookup("core_number", node)
        bet_norm = norm_lookup("betweenness", node)
        eig_norm = norm_lookup("eigenvector", node)
        clustering_raw = max(0.0, min(1.0, node_data.get("clustering", 0.0)))
        open_val = 1.0 - clustering_raw

        achieved = set()
        margin = 0.0

        if deg_norm >= thr_deg:
            achieved.add("hub")
            margin += deg_norm - thr_deg
        else:
            margin -= 0.25 * (thr_deg - deg_norm)

        if core_norm >= thr_core:
            achieved.add("core")
            margin += core_norm - thr_core
        else:
            margin -= 0.2 * (thr_core - core_norm)

        if bet_norm >= thr_bridge:
            achieved.add("bridge")
            margin += bet_norm - thr_bridge
        else:
            margin -= 0.2 * (thr_bridge - bet_norm)

        if eig_norm >= thr_eig:
            achieved.add("influence")
            margin += eig_norm - thr_eig
        else:
            margin -= 0.15 * (thr_eig - eig_norm)

        if open_val >= thr_open:
            achieved.add("open")
            margin += open_val - thr_open
        else:
            margin -= 0.25 * (thr_open - open_val)

        dominance = len(achieved)
        shock = dominance * dominance + 0.6 * margin

        synergy = 0.0
        if "hub" in achieved and "bridge" in achieved:
            synergy += 0.6 + 0.2 * bridge_ratio
        if "open" in achieved and "bridge" in achieved:
            synergy += 0.4 + 0.2 * (1.0 - stretch)
        if "hub" in achieved and "influence" in achieved:
            synergy += 0.4
        if "core" in achieved and "open" in achieved:
            synergy += 0.25

        deg_raw = node_data.get("degree", 0.0)
        if deg_raw > 0:
            neighbor_open = 0.0
            for nbr in graph.neighbors(node):
                nbr_clust = max(0.0, min(1.0, graph.nodes[nbr].get("clustering", 0.0)))
                neighbor_open += 1.0 - nbr_clust
            neighbor_open /= deg_raw
        else:
            neighbor_open = open_val
        exposure = 0.5 * open_val + 0.5 * neighbor_open

        influence_bonus = max(0.0, eig_norm - thr_eig)

        impact = shock
        impact += synergy
        impact += 0.2 * bet_norm + 0.1 * core_norm
        impact += (0.3 + 0.2 * progress) * exposure
        impact += 0.15 * influence_bonus

        penalty = (clustering_raw ** (1.1 + 0.5 * (1.0 - stretch))) * (0.2 + 0.3 * (1.0 - progress))
        impact -= penalty
        impact -= 0.05 * max(0.0, thr_deg - deg_norm)

        if impact > best_value or (impact == best_value and (best_node is None or node < best_node)):
            best_value = impact
            best_node = node

    return best_node
